/**
 * Map backdrops — Natural Earth land outlines (public domain) a zone can draw
 * faintly inside its box (`zone.backdrop`). The paths are generated by
 * scripts/build-backdrops.ts; this module names them and hands them to the
 * engine (`TopologyDesigner.registerBackdrop`) in every render path.
 */
import { BACKDROPS } from './backdrops.generated.js';

export const BACKDROP_NAMES = [
  'world',
  'amer',
  'emea',
  'apac',
  'latam',
] as const;
export type BackdropName = (typeof BACKDROP_NAMES)[number];

export const BACKDROP_LABELS: Readonly<Record<BackdropName, string>> = {
  world: 'World',
  amer: 'North America',
  emea: 'Europe, Middle East & Africa',
  apac: 'Asia-Pacific',
  latam: 'Latin America',
};

export function isBackdropName(v: unknown): v is BackdropName {
  return (
    typeof v === 'string' && (BACKDROP_NAMES as readonly string[]).includes(v)
  );
}

/** Region names people use → the backdrop that shows that region. */
const ALIASES: Record<string, BackdropName> = {
  world: 'world',
  global: 'world',
  amer: 'amer',
  amers: 'amer',
  na: 'amer',
  noram: 'amer',
  'north america': 'amer',
  us: 'amer',
  usa: 'amer',
  emea: 'emea',
  eu: 'emea',
  europe: 'emea',
  africa: 'emea',
  'middle east': 'emea',
  apac: 'apac',
  apj: 'apac',
  asia: 'apac',
  'asia pacific': 'apac',
  'asia-pacific': 'apac',
  anz: 'apac',
  latam: 'latam',
  lata: 'latam',
  sa: 'latam',
  'south america': 'latam',
  'latin america': 'latam',
};

/** The backdrop a region name refers to, or undefined when it names none. */
export function backdropForRegion(name: string): BackdropName | undefined {
  return ALIASES[name.trim().toLowerCase()];
}

interface BackdropEngine {
  registerBackdrop?(
    name: string,
    b: { w: number; h: number; d: string },
  ): unknown;
}

/** Register every backdrop with an engine (idempotent). */
export function registerBackdrops(engine: BackdropEngine | undefined): void {
  if (!engine?.registerBackdrop) return;
  for (const name of BACKDROP_NAMES)
    engine.registerBackdrop(name, BACKDROPS[name]);
}
